import cyclopts

app = cyclopts.App()

@app.default
def status():
    """Show the current status."""
    print("Status: All systems operational")

@app.command
def start():
    """Start the service."""
    print("Service started")

@app.command
def stop():
    """Stop the service."""
    print("Service stopped")

if __name__ == "__main__":
    app()
